def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The full 2-line is the divider; move the non-background object flush
    # against it, then draw an 8-line on the object's opposite side.
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    sep_color = 2
    div_col = next((c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))), None)
    if div_col is not None:
        cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                 if grid[r][c] not in (bg, sep_color)]
        if not cells:
            return out
        left = any(c < div_col for r, c, v in cells)
        if left:
            shift = div_col - 1 - max(c for r, c, v in cells)
            line = min(c for r, c, v in cells) + shift - 1
        else:
            shift = div_col + 1 - min(c for r, c, v in cells)
            line = max(c for r, c, v in cells) + shift + 1
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r][c + shift] = v
        if 0 <= line < w:
            for r in range(h):
                if out[r][line] != sep_color:
                    out[r][line] = 8
        return out

    div_row = next((r for r in range(h) if all(grid[r][c] == sep_color for c in range(w))), None)
    if div_row is not None:
        cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                 if grid[r][c] not in (bg, sep_color)]
        if not cells:
            return out
        above = any(r < div_row for r, c, v in cells)
        if above:
            shift = div_row - 1 - max(r for r, c, v in cells)
            line = min(r for r, c, v in cells) + shift - 1
        else:
            shift = div_row + 1 - min(r for r, c, v in cells)
            line = max(r for r, c, v in cells) + shift + 1
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r + shift][c] = v
        if 0 <= line < h:
            for c in range(w):
                if out[line][c] != sep_color:
                    out[line][c] = 8
        return out
    return out
